n=19
objs=[(3,6,8),(4,13,4),(12,14,1),(14,3,2),(10,8,0)]
markers=set()
for r,c,v in objs:
    markers.update([(r-1,c),(r+1,c),(r,c-1),(r,c+1)])
# horizontal painted from centers; pass own immediate arms, stop at any other arm
G=[[0]*n for _ in range(n)]
for r,c,v in objs:
    if v:
        G[r][c]=v
        for dc in (-1,1):
            for d in range(1,n):
                cc=c+dc*d
                if not 0<=cc<n: break
                if (r,cc) in markers:
                    if d==1: continue
                    break
                G[r][cc]=v
# blank vertical axis of empty cross overrides horizontal track
for r in range(n):
    if (r,8) not in markers: G[r][8]=0
# colored vertical tracks override horizontal/blank horizontal
for r,c,v in objs:
    if v:
        for dr in (-1,1):
            for d in range(1,n):
                rr=r+dr*d
                if not 0<=rr<n: break
                if (rr,c) in markers:
                    if d==1: continue
                    break
                G[rr][c]=v
# keep 3 markers
for r,c in markers: G[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in G))
